/**
 * Shared data contracts. Owned by the orchestrator: module owners import from here
 * and do not edit this file (report needed changes instead).
 *
 * Conventions
 * - Juror lean runs from -10 (certain to convict) to +10 (certain to acquit).
 *   A positive delta always favours the DEFENCE (the player).
 * - Code owns all state. Models only ever return the scorer outputs defined here,
 *   or free text for actors. No model output is applied without code validating it.
 */
import { z } from "zod";

// ───────────────────────── Basics ─────────────────────────

export const Side = z.enum(["defence", "prosecution"]);
export type Side = z.infer<typeof Side>;

export const ObjectionType = z.enum([
  "relevance",
  "hearsay",
  "leading",
  "speculation",
  "assumes_facts",
  "badgering",
]);
export type ObjectionType = z.infer<typeof ObjectionType>;

// ───────────────────────── Case file ─────────────────────────

export const Exhibit = z.object({
  id: z.string().regex(/^E\d+$/),
  title: z.string(),
  kind: z.string(), // "log", "report", "photo description", ...
  text: z.string(), // the full document as the player reads it
});
export type Exhibit = z.infer<typeof Exhibit>;

export const Breaker = z.object({
  /** Every one of these must have been presented to this witness (now or earlier in
   *  the same examination), and at least one must be attached to the current question. */
  exhibitIds: z.array(z.string()).min(1),
  /** What the question must actually put to the witness for the confrontation to count. */
  mustConfront: z.string(),
});
export type Breaker = z.infer<typeof Breaker>;

export const Lie = z.object({
  id: z.string(),
  /** Short public label shown to the player once exposed. */
  label: z.string(),
  /** What the lie is about, so the actor knows when it is in play. */
  topic: z.string(),
  /** What the witness says while the lie is held. The ONLY version the actor sees then. */
  coverStory: z.string(),
  /** The real facts. Released to the actor only after code marks the lie cracked. */
  truth: z.string(),
  /** What the witness admits (and how far they go) once cracked. */
  concession: z.string(),
  /** Alternative ways to crack the lie; any one is enough. */
  breakers: z.array(Breaker).min(1),
});
export type Lie = z.infer<typeof Lie>;

/** A Deepgram Aura voice model id: "aura-<name>-en" (Aura-1) or "aura-2-<name>-en" (Aura-2). */
export const VoiceId = z.string().regex(/^aura-(?:2-)?[a-z]+-[a-z]{2}$/, "Expected an Aura voice id such as aura-2-draco-en.");

export const Witness = z.object({
  id: z.string(),
  name: z.string(),
  role: z.string(), // public one-liner
  calledBy: Side,
  publicStatement: z.string(), // prior statement shown in the case file
  persona: z.string(), // private acting notes: voice, temperament, how they dodge
  knows: z.array(z.string()), // true things they know and will answer honestly
  lies: z.array(Lie),
  /** Text-to-speech voice model id (e.g. "aura-2-draco-en"). Optional; the server falls back. */
  voice: VoiceId.optional(),
});
export type Witness = z.infer<typeof Witness>;

export const PlanStep = z.object({
  topic: z.string(), // what this question should establish
  exhibitIds: z.array(z.string()).default([]), // exhibits the prosecutor presents with it
});
export type PlanStep = z.infer<typeof PlanStep>;

export const Juror = z.object({
  id: z.string(),
  name: z.string(),
  persona: z.string(), // public blurb
  disposition: z.string(), // private: what moves this juror and what leaves them cold
  startLean: z.number().int().min(-10).max(10),
  /** Votes not guilty when final lean >= this; otherwise votes guilty. */
  acquitAt: z.number().int().min(-10).max(10),
});
export type Juror = z.infer<typeof Juror>;

export const CaseFile = z.object({
  id: z.string(),
  title: z.string(),
  charge: z.string(),
  playerSide: z.literal("defence"),
  defendantName: z.string(),
  /** Everything the player and every AI role may see: setting, parties, undisputed facts. */
  publicBrief: z.string(),
  rules: z.object({
    objections: z.array(
      z.object({ type: ObjectionType, name: z.string(), rule: z.string(), example: z.string() }),
    ),
    evidence: z.array(z.string()),
  }),
  /** Ground truth. Never sent to actors or jurors. */
  timeline: z.array(z.object({ time: z.string(), event: z.string(), knownBy: z.array(z.string()) })),
  evidence: z.array(Exhibit),
  /** Exactly three: two called by the prosecution (in order), then the defendant. */
  witnesses: z.array(Witness).length(3),
  prosecution: z.object({
    name: z.string(),
    persona: z.string(),
    theory: z.string(),
    openingPoints: z.array(z.string()),
    closingPoints: z.array(z.string()),
    /** witnessId -> ordered steps. Direct for prosecution witnesses, cross for the defendant. */
    plan: z.record(z.string(), z.array(PlanStep)),
    voice: VoiceId.optional(),
  }),
  judge: z.object({ name: z.string(), persona: z.string(), voice: VoiceId.optional() }),
  /** The clerk's narration is code-written; only its voice is configurable. */
  clerk: z.object({ voice: VoiceId.optional() }).optional(),
  jurors: z.array(Juror).length(5),
});
export type CaseFile = z.infer<typeof CaseFile>;

// ───────────────────────── Scorer outputs (structured model output) ─────────────────────────

export const ClaimVerdict = z.enum(["supported", "unsupported", "contradicted"]);
export type ClaimVerdict = z.infer<typeof ClaimVerdict>;

/** Fact-checker: tags each factual assertion or embedded premise. Pure questions have no claims. */
export const FactCheck = z.object({
  claims: z.array(
    z.object({
      text: z.string(),
      verdict: ClaimVerdict,
      /** Exhibit IDs or record entry IDs relied on. Empty for "unsupported". */
      refs: z.array(z.string()),
      reason: z.string(),
    }),
  ),
  /** True when the speaker, in an opening or closing, gives up their own side's case
   *  (defence admits guilt or asks for a conviction; prosecution says the charge is not proved). */
  concedesOwnCase: z.boolean().default(false),
});
export type FactCheck = z.infer<typeof FactCheck>;

/** Rule check: does this question or statement break any of the six objection rules? */
export const RuleCheck = z.object({
  violations: z.array(
    z.object({
      objection: ObjectionType,
      severity: z.enum(["clear", "arguable"]),
      reason: z.string(),
    }),
  ),
});
export type RuleCheck = z.infer<typeof RuleCheck>;

/** The judge's ruling on one raised objection, decided against the written rules. */
export const Ruling = z.object({
  objection: ObjectionType,
  sustained: z.boolean(),
  ruleCited: z.string(),
  reason: z.string(),
});
export type Ruling = z.infer<typeof Ruling>;

/** Did the question actually put the contradiction to the witness? */
export const Confront = z.object({
  lieId: z.string(),
  confronted: z.boolean(),
  reason: z.string(),
});
export type Confront = z.infer<typeof Confront>;

export const JurorDelta = z.object({
  jurorId: z.string(),
  delta: z.number().int().min(-2).max(2),
  reason: z.string(),
});
export type JurorDelta = z.infer<typeof JurorDelta>;

/** One entry per juror, in case-file order. */
export const JuryUpdate = z.object({ jurors: z.array(JurorDelta) });
export type JuryUpdate = z.infer<typeof JuryUpdate>;

/** Test-time grader: did a witness answer abandon a lie that code still marks as held? */
export const LeakCheck = z.object({
  leaks: z.array(z.object({ lieId: z.string(), abandoned: z.boolean(), quote: z.string() })),
});
export type LeakCheck = z.infer<typeof LeakCheck>;

// ───────────────────────── Trial record and state ─────────────────────────

export const Phase = z.enum([
  "case_review",
  "opening", // prosecution opens, then the player
  "w1_direct",
  "w1_cross",
  "w2_direct",
  "w2_cross",
  "w3_cross", // prosecutor crosses the defendant; the player objects
  "closing", // prosecution closes, then the player has the last word
  "verdict", // terminal; replay data is available
]);
export type Phase = z.infer<typeof Phase>;

export type Speaker =
  | { kind: "player" }
  | { kind: "prosecutor" }
  | { kind: "witness"; witnessId: string }
  | { kind: "judge" }
  | { kind: "clerk" }; // code-written narration, never a model

export type EntryKind =
  | "statement" // openings, closings
  | "question"
  | "answer"
  | "objection"
  | "ruling"
  | "narration";

/** Facts established by code and handed to the jury scorer. Models never create these. */
export type EventTag =
  | { type: "lie_cracked"; lieId: string; witnessId: string; by: Side; label: string }
  | { type: "concession"; by: Side } // a side gave up its own case in a statement
  | { type: "claim_flagged"; by: Side; verdict: "unsupported" | "contradicted"; claim: string }
  | { type: "objection_sustained"; by: Side; ground: ObjectionType }
  | { type: "objection_overruled"; by: Side; ground: ObjectionType }
  | { type: "question_withdrawn"; by: Side } // struck after a sustained objection
  | { type: "exhibit_admitted"; by: Side; exhibitId: string };

export interface RecordEntry {
  id: string; // "r1", "r2", ... in order
  phase: Phase;
  speaker: Speaker;
  kind: EntryKind;
  text: string;
  exhibitIds: string[];
  /** Struck from the record (sustained objection). Still displayed, greyed out. */
  stricken: boolean;
  tags: EventTag[];
  factCheck?: FactCheck;
}

export interface LeanChange {
  entryId: string; // the last record entry of the exchange that caused it
  rawDelta: number; // what the scorer returned
  delta: number; // after code applied credibility scaling and clamping
  leanAfter: number;
  reason: string;
  tags: EventTag[];
}

export interface UsageEntry {
  call: string; // e.g. "actor:witness:renn", "scorer:jury"
  kind: "actor" | "scorer";
  inputTokens: number; // uncached input
  cacheReadTokens: number;
  cacheWriteTokens: number;
  outputTokens: number;
  costUsd: number;
  ms: number;
  stopReason: string | null;
  refused: boolean;
}

export interface UsageTotals {
  calls: number;
  inputTokens: number;
  cacheReadTokens: number;
  cacheWriteTokens: number;
  outputTokens: number;
  costUsd: number;
  refusals: number;
}

/** Voice spend for one trial. Counted by the server, never by the engine. */
export interface VoiceUsage {
  /** Characters sent to text-to-speech (cache hits are free and not counted). */
  ttsChars: number;
  ttsRequests: number;
  /** Seconds of recorded audio sent to speech-to-text. */
  sttSeconds: number;
  sttRequests: number;
  costUsd: number;
  /** Bumped on every billable call, so the newest copy can be told apart. */
  seq: number;
}

export type PlayerAction =
  | { type: "begin" } // leave case review; the prosecution opens
  | { type: "opening"; text: string }
  | { type: "ask"; text: string; exhibitIds: string[] } // cross-examination question
  | { type: "end_cross" } // "no further questions"
  | { type: "object"; ground: ObjectionType } // only while pending === "objection_window"
  | { type: "pass" } // let the prosecutor's question stand
  | { type: "closing"; text: string };

/** What the engine is waiting for. null while the engine is working. */
export type Pending = "begin" | "opening" | "question" | "objection_window" | "closing" | null;

export interface Budgets {
  directQuestions: number; // prosecutor questions per prosecution witness
  crossQuestions: number; // player questions per cross
  clientCrossQuestions: number; // prosecutor questions to the defendant
}
export const DEFAULT_BUDGETS: Budgets = { directQuestions: 4, crossQuestions: 8, clientCrossQuestions: 6 };

export interface Verdict {
  outcome: "not_guilty" | "guilty" | "hung";
  votes: { jurorId: string; vote: "not_guilty" | "guilty"; finalLean: number }[];
}

/** One stored jury scorer request, kept so the same transcript can be re-scored for consistency. */
export interface JuryCallLog {
  uptoEntryId: string; // record is everything up to and including this entry
  exchangeEntryIds: string[];
  tags: EventTag[];
  leansBefore: Record<string, number>;
  result: JuryUpdate | null; // null = scorer refused or failed; no lean moved
}

export interface TrialState {
  id: string;
  caseId: string;
  budgets: Budgets;
  phase: Phase;
  pending: Pending;
  /** Witness on the stand, if any. */
  witnessId: string | null;
  questionsLeft: number;
  record: RecordEntry[];
  admitted: string[]; // exhibit IDs presented in court so far
  /** Exhibits presented to each witness, keyed by witnessId. */
  shown: Record<string, string[]>;
  lieStatus: Record<string, "held" | "cracked">;
  credibility: Record<Side, number>; // 0..100, starts at 70
  jurors: Record<string, { lean: number; log: LeanChange[] }>;
  juryCalls: JuryCallLog[];
  usage: UsageEntry[];
  verdict: Verdict | null;
  startedAt: string;
  endedAt: string | null;
}

// ───────────────────────── What the browser may see ─────────────────────────

export interface PlayerView {
  id: string;
  phase: Phase;
  pending: Pending;
  witnessId: string | null;
  questionsLeft: number;
  record: RecordEntry[]; // factCheck is included only on the player's own entries
  admitted: string[];
  exposedLies: { lieId: string; witnessId: string; label: string }[];
  credibility: Record<Side, number>;
  usage: UsageTotals;
  /** Public parts of the case file only: no timeline, no lies, no private personas. */
  caseInfo: {
    title: string;
    charge: string;
    defendantName: string;
    publicBrief: string;
    rules: CaseFile["rules"];
    evidence: Exhibit[];
    witnesses: { id: string; name: string; role: string; calledBy: Side; publicStatement: string }[];
    jurors: { id: string; name: string; persona: string }[];
    prosecutorName: string;
    judgeName: string;
  };
  /** Voice (text-to-speech and speech-to-text) spend, added by the server beside `usage`.
   *  Absent when the server has no voice support or nothing has been spent. */
  voice?: VoiceUsage;
  /** Present only once phase === "verdict". Juror leans stay hidden until then. */
  result: null | {
    verdict: Verdict;
    replay: { jurorId: string; name: string; startLean: number; acquitAt: number; log: LeanChange[] }[];
  };
}

/** Pushed to the browser over SSE. */
export type TrialEvent =
  | { type: "entry_start"; entryId: string; speaker: Speaker; kind: EntryKind; exhibitIds: string[] }
  | { type: "token"; entryId: string; text: string }
  | { type: "entry_end"; entry: RecordEntry }
  | { type: "entry_discard"; entryId: string } // a streamed reply that never made the record
  | { type: "notice"; text: string } // e.g. a refused turn
  | { type: "state"; view: PlayerView }
  | { type: "error"; message: string };
